namespace Acme.NewRelic.Synthetics;

/// <summary>
/// Minimal NerdGraph transport: POSTs {query, variables} JSON to the GraphQL
/// endpoint with the documented API-Key header, retries HTTP 429 with doubling
/// delays through an injected delay function, and fails closed on top-level
/// GraphQL errors instead of handing back partial data.
/// </summary>
public sealed class NerdGraphClient
{
    const int MaxAttempts = 3;
    const string RedactedKey = "[redacted-api-key]";

    readonly Uri _endpoint;
    readonly string _apiKey;
    readonly HttpClient _http;
    readonly Func<TimeSpan, Task> _delay;

    public NerdGraphClient(
        string endpointUrl,
        string apiKey,
        HttpMessageHandler handler,
        Func<TimeSpan, Task> delay)
    {
        ArgumentException.ThrowIfNullOrEmpty(endpointUrl);
        ArgumentException.ThrowIfNullOrEmpty(apiKey);
        ArgumentNullException.ThrowIfNull(handler);
        ArgumentNullException.ThrowIfNull(delay);
        _endpoint = new Uri(endpointUrl);
        _apiKey = apiKey;
        _http = new HttpClient(handler, disposeHandler: false);
        _delay = delay;
    }

    /// <summary>
    /// Executes one GraphQL document and returns the response's data node.
    /// Throws <see cref="NerdGraphHttpException"/> on non-success HTTP statuses
    /// (429 only after retries are exhausted) and
    /// <see cref="NerdGraphResponseException"/> when the response carries
    /// top-level GraphQL errors or no data at all.
    /// </summary>
    public async Task<JsonNode> QueryAsync(string document, JsonNode? variables)
    {
        var body = new JsonObject
        {
            ["query"] = document,
            ["variables"] = variables ?? new JsonObject(),
        }.ToJsonString();

        for (var attempt = 1; ; attempt++)
        {
            using var request = new HttpRequestMessage(HttpMethod.Post, _endpoint)
            {
                Content = new StringContent(body, Encoding.UTF8, "application/json"),
            };
            request.Headers.TryAddWithoutValidation("API-Key", _apiKey);

            using var response = await _http.SendAsync(request).ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                if ((int)response.StatusCode == 429 && attempt < MaxAttempts)
                {
                    await _delay(TimeSpan.FromSeconds(1 << (attempt - 1))).ConfigureAwait(false);
                    continue;
                }
                throw new NerdGraphHttpException((int)response.StatusCode);
            }

            var text = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
            // Scrubbing at the transport boundary is what guarantees the
            // "key never appears in exception text" invariant even when the
            // server echoes the key back: nothing derived from a response -
            // GraphQL error messages, mutation error descriptions, data - can
            // still contain it.
            text = text.Replace(_apiKey, RedactedKey, StringComparison.Ordinal);

            JsonNode? root;
            try
            {
                root = JsonNode.Parse(text);
            }
            catch (JsonException)
            {
                throw new NerdGraphResponseException(
                    new[] { "the NerdGraph response body was not valid JSON" });
            }

            if (root?["errors"] is JsonArray errors && errors.Count > 0)
            {
                throw new NerdGraphResponseException(errors
                    .Select(e => (string?)e?["message"] ?? "unspecified GraphQL error")
                    .ToArray());
            }
            if (root?["data"] is not JsonNode data)
            {
                throw new NerdGraphResponseException(
                    new[] { "the NerdGraph response carried no data" });
            }
            return data;
        }
    }
}
"}

