        }
    }

    static void Validate(DesiredScriptApiMonitor desired)
    {
        if (!PeriodEnum.Contains(desired.Period, StringComparer.Ordinal))
        {
            throw new ArgumentException(
                $"Unknown monitor period '{desired.Period}'; expected one of the documented enum values.",
                nameof(desired));
        }
        if (!StatusEnum.Contains(desired.Status, StringComparer.Ordinal))
        {
            throw new ArgumentException(
                $"Unknown monitor status '{desired.Status}'; expected ENABLED or DISABLED.",
                nameof(desired));
        }
        if (desired.Name.Contains('\'') || desired.Name.Contains('\\'))
        {
            throw new ArgumentException(
                "Monitor names containing a single quote or backslash cannot be embedded "
                + "safely in an entity-search query and are rejected.",
                nameof(desired));
        }
    }

    async Task<DiscoveredMonitor?> DiscoverAsync(string name)
    {
        var variables = new JsonObject
        {
            ["query"] = BaseEntityQuery + " AND name = '" + name + "'",
        };
        var data = await _client.QueryAsync(DiscoveryDocument, variables).ConfigureAwait(false);
        var results = data["actor"]?["entitySearch"]?["results"]
            ?? throw new NerdGraphResponseException(
                new[] { "entity search response is missing actor.entitySearch.results" });

        var entities = (results["entities"] as JsonArray
            ?? throw new NerdGraphResponseException(
                new[] { "entity search response is missing the entities list" }))
            .Where(e => e?["guid"] is not null)
            .ToList();

        if (entities.Count > 1 || results["nextCursor"] is not null)
        {
            throw new AmbiguousMonitorException(
                $"Entity search for monitor '{name}' matched more than one monitor "
                + "(or was truncated); refusing to guess which one to reconcile.");
        }
        if (entities.Count == 0)
        {
            return null;
        }

        var entity = entities[0]!;
        var tags = new Dictionary<string, IReadOnlyList<string>>(StringComparer.Ordinal);
        if (entity["tags"] is JsonArray tagArray)
        {
            foreach (var tag in tagArray)
            {
                var key = (string?)tag?["key"];
                if (key is null)
                {
                    continue;
                }
                tags[key] = (tag!["values"] as JsonArray ?? new JsonArray())
                    .Select(v => (string?)v ?? "")
                    .ToList();
            }
        }
        return new DiscoveredMonitor(
            Guid: (string)entity["guid"]!,
            Name: (string?)entity["name"] ?? name,
            AccountId: (long?)entity["accountId"] ?? 0,
            MonitorType: (string?)entity["monitorType"] ?? "",
            Tags: tags);
    }

    async Task<string> CreateAsync(DesiredScriptApiMonitor desired)
    {
        if (desired.Script is null)
        {
            // The documented create input requires a script; inventing one (or
            // sending none) is exactly the clobbering failure this reconciler
            // exists to prevent, so a script-less desired state can only update.
            throw new InvalidOperationException(
                $"Monitor '{desired.Name}' does not exist and the desired state has no script; "
                + "creating a scripted API monitor requires the script, so refusing to create.");
        }
        var variables = new JsonObject
        {
            ["accountId"] = _accountId,
            ["monitor"] = BuildMonitorInput(desired, includeScript: true),
        };
        var data = await _client.QueryAsync(CreateDocument, variables).ConfigureAwait(false);
        return ReadMutationResult(data, "syntheticsCreateScriptApiMonitor", fallbackGuid: null);
    }

    async Task<string> UpdateAsync(string guid, DesiredScriptApiMonitor desired)
    {
        var variables = new JsonObject
        {
            ["guid"] = guid,
            ["monitor"] = BuildMonitorInput(desired, includeScript: desired.Script is not null),
        };
        var data = await _client.QueryAsync(UpdateDocument, variables).ConfigureAwait(false);
        return ReadMutationResult(data, "syntheticsUpdateScriptApiMonitor", fallbackGuid: guid);
    }

    JsonObject BuildMonitorInput(DesiredScriptApiMonitor desired, bool includeScript)
    {
        var monitor = new JsonObject
        {
            ["name"] = desired.Name,
            ["period"] = desired.Period,
            ["status"] = desired.Status,
            ["locations"] = new JsonObject
            {
                ["public"] = new JsonArray(
                    desired.PublicLocations.Select(l => (JsonNode)l).ToArray()),
            },
            ["runtime"] = new JsonObject
            {
                ["runtimeType"] = RuntimeType,
                ["runtimeTypeVersion"] = RuntimeTypeVersion,
                ["scriptLanguage"] = ScriptLanguage,
            },
        };
        if (desired.ApdexTarget is double apdexTarget)
        {
            monitor["apdexTarget"] = apdexTarget;
        }
        if (includeScript)
        {
            monitor["script"] = desired.Script;
        }
        return monitor;
    }

    static string ReadMutationResult(JsonNode data, string field, string? fallbackGuid)
    {
        var payload = data[field]
            ?? throw new NerdGraphResponseException(
                new[] { $"mutation response is missing the {field} payload" });

        if (payload["errors"] is JsonArray errors && errors.Count > 0)
        {
            throw new SyntheticsMutationException(errors
                .Select(e => new MutationError(
                    Description: (string?)e?["description"] ?? "unspecified mutation error",
                    Type: (string?)e?["type"] ?? "UNKNOWN"))
                .ToList());
        }

        return (string?)payload["monitor"]?["guid"]
            ?? fallbackGuid
            ?? throw new NerdGraphResponseException(
                new[] { $"the {field} payload carried no monitor guid" });
    }

    async Task<(IReadOnlyList<string> Keys, IReadOnlyList<string> Errors)> ReplaceTagsAsync(
        string guid,
        IReadOnlyDictionary<string, IReadOnlyList<string>> desiredTags,
        IReadOnlyDictionary<string, IReadOnlyList<string>>? currentTags)
    {
        var keys = desiredTags.Keys
            .Where(k => currentTags is null
                || !currentTags.TryGetValue(k, out var current)
                || !SameValues(desiredTags[k], current))
            .OrderBy(k => k, StringComparer.Ordinal)
            .ToList();
        if (keys.Count == 0)
        {
            return (Array.Empty<string>(), Array.Empty<string>());
        }

        var variables = new JsonObject
        {
            ["guid"] = guid,
            ["tags"] = new JsonArray(keys
                .Select(k => (JsonNode)new JsonObject
                {
                    ["key"] = k,
                    ["values"] = new JsonArray(
                        desiredTags[k].Select(v => (JsonNode)v).ToArray()),
                })
                .ToArray()),
        };

        // The monitor mutation already succeeded, so any tagging failure -
        // mutation errors, HTTP/GraphQL failures, plain transport exceptions -
        // is a partial success reported through TagErrors, never a rollback.
        try
        {
            var data = await _client.QueryAsync(ReplaceTagsDocument, variables)
                .ConfigureAwait(false);
            var payload = data["taggingReplaceTagsOnEntity"];
            if (payload is null)
            {
                return (Array.Empty<string>(),
                    new[] { "the tagging mutation returned no payload" });
            }
            if (payload["errors"] is JsonArray errors && errors.Count > 0)
            {
                return (Array.Empty<string>(), errors
                    .Select(e => (string?)e?["message"] ?? "unspecified tagging error")
                    .ToList());
            }
            return (keys, Array.Empty<string>());
        }
        catch (Exception ex)
        {
            return (Array.Empty<string>(),
                new[] { $"tag replacement failed: {ex.Message}" });
        }
    }

    static bool SameValues(IReadOnlyList<string> desired, IReadOnlyList<string> current)
    {
        return desired
            .OrderBy(v => v, StringComparer.Ordinal)
            .SequenceEqual(current.OrderBy(v => v, StringComparer.Ordinal), StringComparer.Ordinal);
    }
}
